EDIT_TIMEOUT = 1800
LOOP_BUDGET_LIMIT = 86340


def run(request, story, chapters, edits, edit_queue_workflow_id):
    numbers = [chapter["number"] for chapter in chapters]
    queue = []

    for edit in edits:
        if edit.get("chapter") in numbers and len(edit.get("requests") or []) > 0:
            queue.append({"chapter": edit["chapter"], "requests": edit["requests"]})

    iterations = max(len(queue), 1)
    edit_timeout = request.get("edit_timeout_seconds", EDIT_TIMEOUT)
    budget = min(iterations * edit_timeout, LOOP_BUDGET_LIMIT)
    config = {}

    for key in ("revision_workflow_id", "max_revisions"):
        if key in request:
            config[key] = request[key]

    return {
        "needs_final_edits": len(queue) > 0,
        "settings": {
            "workflow_id": request.get("edit_queue_workflow_id", edit_queue_workflow_id),
            "max_iterations": iterations,
            "child_timeout_seconds": edit_timeout,
            "budget_seconds": request.get("edit_budget_seconds", budget),
            "state": {"queue": queue, "chapters": chapters, "story": story, "config": config},
        },
        "chapters": chapters,
    }
